//! Real-executable GameRef native vectors, generated by `res_vectors.py game`.
mod support;
use serde_json::Value;
use slr_resource::node as n;

#[test]
fn game_query_natives_match_oracle_vectors() {
    let dir = std::env::var_os("SLR_GAME_VECTORS")
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| {
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../re/out/res")
        });
    let mut checked = 0;
    let mut files = 0;
    for name in [
        "create",
        "create_native",
        "getInfoI",
        "getInfoS",
        "setPos",
        "setMatrix",
        "setState",
        "isEmpty",
        "isScripted",
        "getScriptInstance",
        "getDetail",
        "getPos",
        "getOri",
        "getVel",
        "setParent",
        "queueEvent",
    ] {
        let Ok(text) = std::fs::read_to_string(dir.join(format!("res_game_{name}.jsonl"))) else {
            eprintln!("SKIP: no GameRef {name} oracle vectors");
            continue;
        };
        files += 1;
        assert!(!text.trim().is_empty(), "empty vectors for {name}");
        let binding = n::GAME_REF_BINDINGS
            .iter()
            .find(|b| {
                b.name
                    == if name.starts_with("getInfo") {
                        "getInfo"
                    } else {
                        name
                    }
                    && (!name.ends_with("S") || b.sig == "(ILjava.lang.String;)I")
            })
            .unwrap_or_else(|| panic!("missing native {name}"));
        for line in text.lines().filter(|l| !l.is_empty()) {
            let row: Value = serde_json::from_str(line).unwrap();
            let a = &row["args"];
            let mut host = n::ResHost::new();
            let mut secondary_state =
                n::Container::new(a["secondary_mode"].as_i64().unwrap_or(1) as i32, 0);
            if a["secondary_envelope"].as_bool().unwrap_or(true) {
                secondary_state.instance = Some(n::GameInstance::default());
            }
            let secondary = host.add_container(secondary_state);
            host.set_container_gate(secondary, a["secondary_gate"].as_bool().unwrap_or(false));
            let dispatch = 0xDDDD;
            let mut container = n::Container::new(a["mode"].as_i64().unwrap() as i32, 9);
            container.detail = a["detail"].as_u64().unwrap() as u32;
            if a["envelope"].as_bool().unwrap() {
                container.instance = Some(n::GameInstance {
                    info: a["child"].as_bool().unwrap().then_some(n::InfoTarget {
                        resource: secondary,
                        receiver: dispatch,
                        id: a["info_id"].as_u64().unwrap_or(0x333) as u32,
                        result: 0xbeef,
                    }),
                    script: a["script"].as_u64().unwrap() as u32,
                    member: a["member"].as_bool().unwrap(),
                    child: a["child"].as_bool().unwrap(),
                    child_script: a["script"].as_u64().unwrap() as u32,
                    child_compiled: a["child_compiled"].as_bool().unwrap(),
                    class_match: a["class_match"].as_bool().unwrap(),
                });
            }
            let c = host.add_container(container);
            let node = host.add_node_for_test(
                a["node_id"].as_u64().unwrap() as u32,
                if a["container"].as_bool().unwrap() {
                    c
                } else {
                    0
                },
            );
            if a["node"].as_bool().unwrap() {
                host.bind_object(7, node);
            }
            host.set_gate_refused(a["gate"].as_bool().unwrap());
            host.set_spatial(node, [[0x3fc00000, 0xc0200000, 0x80000000]; 3]);
            let name_word = if a["name"].as_bool().unwrap() {
                host.intern("Engine")
            } else {
                0
            };
            let mut inputs = Vec::new();
            if let Some(vectors) = a["vectors"].as_array() {
                for (i, v) in vectors.iter().enumerate() {
                    inputs.push(if a["nulls"].as_u64().unwrap() & (1 << i) != 0 {
                        0
                    } else {
                        host.intern_vector(std::array::from_fn(|j| v[j].as_u64().unwrap() as u32))
                    });
                }
            }

            let mut created = n::Container::new(1, 0x55);
            if a["envelope"].as_bool().unwrap() {
                created.instance = Some(n::GameInstance {
                    script: a["script"].as_u64().unwrap() as u32,
                    ..n::GameInstance::default()
                });
            }
            let created = host.add_container(created);
            let first = host.add_node_for_test(
                0,
                if a["first_bound"].as_bool().unwrap_or(true) {
                    created
                } else {
                    0
                },
            );
            host.bind_object(0x777, first);
            let default = host.add_node_for_test(
                0,
                if a["default_bound"].as_bool().unwrap_or(false) {
                    created
                } else {
                    0
                },
            );
            host.bind_object(n::DEFAULT_RESOURCE_WORD, default);
            host.set_created_result(if a["child"].as_bool().unwrap() {
                created
            } else {
                0
            });
            let words = match name {
                "create" | "create_native" => vec![
                    7,
                    if a["first"].as_bool().unwrap_or(true) {
                        0x777
                    } else {
                        0
                    },
                    0x456,
                    0x789,
                    0xabc,
                ],
                "getInfoI" | "getInfoS" => vec![7, 0x456, 0x789],
                "setPos" | "setMatrix" | "setState" => {
                    let count = match name {
                        "setPos" => 1,
                        "setMatrix" => 2,
                        _ => 4,
                    };
                    std::iter::once(7)
                        .chain(inputs[..count].iter().copied())
                        .collect()
                }
                "setParent" => vec![7, 0x777],
                "queueEvent" => vec![7, 0x777, 0x456, 0x999],
                _ => vec![7, name_word],
            };
            let got = support::invoke(&mut host, binding, &words);
            let result = if matches!(name, "getPos" | "getOri" | "getVel") {
                let labels = if name == "getOri" {
                    ["y", "p", "r"]
                } else {
                    ["x", "y", "z"]
                };
                let fields: Vec<Value> = got
                    .and_then(|v| host.vector(v))
                    .map(|v| {
                        labels
                            .into_iter()
                            .zip(v)
                            .map(|(k, w)| serde_json::json!([k, w]))
                            .collect()
                    })
                    .unwrap_or_default();
                serde_json::json!({"present":got.unwrap_or(0)!=0,"fields":fields})
            } else if matches!(name, "create" | "create_native") {
                let state = host.node(host.object_node(7));
                serde_json::json!({"ret":got,"id":state.map(|n|n.id),"bound":state.map(|n|n.container!=0)})
            } else if binding.sig.ends_with('V') {
                assert_eq!(got, None);
                serde_json::json!({})
            } else {
                serde_json::json!({"ret":got})
            };
            assert_eq!(result, row["result"], "{name} row {} result", row["id"]);
            support::assert_record(&host, binding, &words, got);
            let resource_identity = |word| {
                if word == c {
                    serde_json::json!("primary")
                } else if word == secondary {
                    serde_json::json!("secondary")
                } else {
                    serde_json::json!(word)
                }
            };
            let node_identity = |word| {
                if word == node {
                    serde_json::json!("node")
                } else {
                    serde_json::json!(word)
                }
            };
            let mut events = Vec::<Value>::new();
            for event in host.events() {
                match event {
                    n::ResourceEvent::Create { native, args } => events.push(serde_json::json!(
                        std::iter::once(serde_json::json!("create"))
                            .chain(std::iter::once(serde_json::json!(native)))
                            .chain(args.iter().map(|w| serde_json::json!(w)))
                            .collect::<Vec<_>>()
                    )),
                    n::ResourceEvent::CreatedInstance { container } => {
                        assert_eq!(*container, created);
                        events.push(serde_json::json!(["instance", "created"]));
                    }
                    n::ResourceEvent::Info {
                        receiver,
                        id,
                        first,
                        second,
                    } => events.push(serde_json::json!([
                        "info",
                        if *receiver == dispatch {
                            serde_json::json!("dispatch")
                        } else {
                            serde_json::json!(receiver)
                        },
                        id,
                        first,
                        second
                    ])),
                    n::ResourceEvent::Field { object, name } => events.push(serde_json::json!([
                        "field",
                        if *object == 0 {
                            -1
                        } else {
                            inputs.iter().position(|w| w == object).unwrap() as i32
                        },
                        name
                    ])),
                    n::ResourceEvent::Command {
                        node: called,
                        format,
                        values,
                    } => {
                        events.push(serde_json::json!(["command", format, values]));
                        events.push(serde_json::json!(["apply", node_identity(*called)]));
                    }
                    n::ResourceEvent::Fetch { container } => {
                        events.push(serde_json::json!(["fetch", resource_identity(*container)]))
                    }
                    n::ResourceEvent::ReadVector { node: called, kind } => {
                        events.push(serde_json::json!(["read", kind, node_identity(*called)]))
                    }
                    n::ResourceEvent::Parent {
                        node: called,
                        parent,
                    } => events.push(serde_json::json!([
                        "parent",
                        node_identity(*called),
                        parent
                    ])),
                    n::ResourceEvent::Queue {
                        node: called,
                        resource,
                        event,
                        text,
                    } => events.push(serde_json::json!([
                        "queue",
                        node_identity(*called),
                        resource,
                        event,
                        text,
                        0
                    ])),
                    n::ResourceEvent::Gate { container, mask } => events.push(serde_json::json!([
                        "gate",
                        resource_identity(*container),
                        mask,
                        0,
                        0
                    ])),
                    n::ResourceEvent::Materialise { container } => {
                        events.push(serde_json::json!([
                            "materialise",
                            resource_identity(*container)
                        ]))
                    }
                    n::ResourceEvent::Class { name } => {
                        events.push(serde_json::json!(["class", name]))
                    }
                    _ => panic!("unexpected GameRef engine call {event:?}"),
                }
            }
            assert_eq!(
                events,
                row["events"].as_array().unwrap().clone(),
                "{name} row {} events",
                row["id"]
            );
            checked += 1;
        }
    }
    if files == 0 {
        eprintln!("SLR_ORACLE_SKIPPED: game_query_natives_match_oracle_vectors");
    } else {
        assert_eq!(files, 16, "incomplete GameRef vectors");
        assert!(checked >= 306);
    }
    eprintln!("replayed {checked} GameRef rows across {files} files");
}

#[test]
#[should_panic(expected = "non-null vector argument must be supplied by the VM")]
fn an_unknown_non_null_transform_argument_is_rejected() {
    let mut host = n::ResHost::new();
    let node = host.add_node_for_test(9, 0);
    host.bind_object(7, node);
    let binding = n::GAME_REF_BINDINGS
        .iter()
        .find(|b| b.impl_addr == n::SET_POS)
        .unwrap();
    support::invoke(&mut host, binding, &[7, 0xDEAD]);
}

#[test]
fn transforms_read_real_vm_object_fields() {
    use slr_vm::host::{CallInfo, VmHost};
    use slr_vm::values::Value as VmValue;
    let dir = std::env::var_os("SLR_GAME_VECTORS")
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| {
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../re/out/res")
        });
    let Ok(text) = std::fs::read_to_string(dir.join("res_game_setState.jsonl")) else {
        eprintln!("SLR_ORACLE_SKIPPED: transforms_read_real_vm_object_fields");
        return;
    };
    let row: Value = serde_json::from_str(text.lines().next().unwrap()).unwrap();
    let mut vm = VmHost::new();
    support::vector_classes(&mut vm);
    n::install(&mut vm);
    n::reset_res();
    n::with_res(|host| {
        let node = host.add_node_for_test(9, 0);
        host.bind_object(7, node);
    });
    let mut args = Vec::new();
    for (i, components) in row["args"]["vectors"]
        .as_array()
        .unwrap()
        .iter()
        .enumerate()
    {
        let object = vm
            .alloc_object(if i == 1 {
                "java.lang.Ypr"
            } else {
                "java.lang.Vector3"
            })
            .unwrap();
        vm.objects[(object - 0x1000) as usize].fields = components
            .as_array()
            .unwrap()
            .iter()
            .map(|v| VmValue::float(f32::from_bits(v.as_u64().unwrap() as u32)))
            .collect();
        args.push(VmValue::reference(object));
    }
    args.reverse();
    args.push(VmValue::reference(7));
    let binding = n::GAME_REF_BINDINGS
        .iter()
        .find(|b| b.impl_addr == n::SET_STATE)
        .unwrap();
    assert_eq!(
        n::bridge(
            &mut vm,
            &CallInfo {
                jvm: 0,
                thread: 0,
                args: &args,
                class: binding.class,
                name: binding.name,
                sig: binding.sig
            }
        ),
        None
    );
    let want = row["events"]
        .as_array()
        .unwrap()
        .iter()
        .find(|event| event[0] == "command")
        .unwrap();
    n::with_res(|host| {
        let (format, values) = host
            .events()
            .iter()
            .find_map(|event| {
                if let n::ResourceEvent::Command { format, values, .. } = event {
                    Some((format, values))
                } else {
                    None
                }
            })
            .unwrap();
        assert_eq!(serde_json::json!(["command", format, values]), *want);
    });
}

#[test]
fn vector_getters_reject_missing_return_classes() {
    use slr_vm::host::{CallInfo, VmHost};
    use slr_vm::values::Value as VmValue;
    for addr in [n::GET_POS, n::GET_ORI, n::GET_VEL] {
        let mut vm = VmHost::new();
        n::install(&mut vm);
        n::reset_res();
        n::with_res(|host| {
            let node = host.add_node_for_test(9, 0);
            host.bind_object(7, node);
            host.set_spatial(node, [[1, 2, 3]; 3]);
        });
        let binding = n::GAME_REF_BINDINGS
            .iter()
            .find(|b| b.impl_addr == addr)
            .unwrap();
        let args = [VmValue::reference(7)];
        let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            n::bridge(
                &mut vm,
                &CallInfo {
                    jvm: 0,
                    thread: 0,
                    args: &args,
                    class: binding.class,
                    name: binding.name,
                    sig: binding.sig,
                },
            )
        }));
        let failure = result.expect_err("missing class returned an invalid JVM object reference");
        let message = failure
            .downcast_ref::<String>()
            .map(String::as_str)
            .or_else(|| failure.downcast_ref::<&str>().copied())
            .unwrap_or("");
        assert!(
            message.contains("vector return class must be loaded"),
            "{message}"
        );
        assert!(vm.objects.is_empty());
    }
}
